//! The Agent Skills that `apic skill` prints and installs: the directories
//! under `skills/` in this repository, compiled into the binary so a
//! project gets them from `apic init` or `apic skill install` without the
//! repository or a network. The pack is apic (how to run, write and test
//! requests with apic), api-design (how to design the API those requests
//! call) and api-security (how to keep it safe and how to prove it with
//! apic). Each `SKILL.md` is hand-written; apic's `references/` is
//! generated by `task skill` and a test in `scripts/skilldocs` keeps it
//! current, and the same test checks every skill's front matter and the
//! commands it names.

#![forbid(unsafe_code)]

use std::collections::BTreeMap;

/// Every skill directory with its files, by path relative to the skill.
/// The build script writes it from the tree on disk.
static PACK: &[(&str, &[(&str, &str)])] = include!(concat!(env!("OUT_DIR"), "/pack.rs"));

/// The primary skill's directory name, the one `apic skill` prints without
/// an argument. Every skill is installed under its own name.
pub const NAME: &str = "apic";

/// Lists the skills in the pack, [`NAME`] first and the rest sorted, each
/// being a directory under `skills/`.
pub fn names() -> Vec<String> {
    let mut out = vec![NAME.to_string()];
    out.extend(
        PACK.iter()
            .map(|(name, _)| *name)
            .filter(|name| *name != NAME)
            .map(str::to_string),
    );
    out
}

/// Reports whether `name` is a skill in the pack.
pub fn has(name: &str) -> bool {
    name == NAME || PACK.iter().any(|(n, _)| *n == name)
}

/// Returns the named skill's files by path relative to its directory
/// (`SKILL.md`, `references/…`), or `None` for a name not in the pack.
pub fn files(name: &str) -> Option<BTreeMap<String, String>> {
    let (_, files) = PACK.iter().find(|(n, _)| *n == name)?;
    Some(
        files
            .iter()
            .map(|(path, text)| (path.to_string(), text.to_string()))
            .collect(),
    )
}

/// Lists the named skill's file paths, `SKILL.md` first and the rest
/// sorted; empty for a name not in the pack.
pub fn paths(name: &str) -> Vec<String> {
    files(name).map(|all| paths_of(&all)).unwrap_or_default()
}

/// Orders a skill's files as [`files`] returns them: `SKILL.md` first, the
/// rest sorted.
pub fn paths_of(all: &BTreeMap<String, String>) -> Vec<String> {
    let mut out = vec!["SKILL.md".to_string()];
    out.extend(all.keys().filter(|p| *p != "SKILL.md").cloned());
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The pack the binary carries must be the directories on disk that
    /// hold a `SKILL.md`, each with at least one reference.
    #[test]
    fn pack_is_every_directory_on_disk() {
        let root = concat!(env!("CARGO_MANIFEST_DIR"), "/../../skills");
        let mut on_disk: Vec<String> = std::fs::read_dir(root)
            .expect("skills directory")
            .flatten()
            .filter(|e| e.path().join("SKILL.md").is_file())
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .collect();
        on_disk.sort();
        let mut got = names();
        got.sort();
        assert_eq!(got, on_disk, "the binary's pack against skills/ on disk");
        assert_eq!(names()[0], NAME);
        for name in names() {
            let paths = paths(&name);
            assert!(
                paths.len() >= 2 && paths[0] == "SKILL.md",
                "{name}: {paths:?}; a skill is SKILL.md and at least one reference"
            );
            assert!(has(&name));
        }
        assert!(!has("nope"));
        assert!(files("nope").is_none());
        assert!(paths("nope").is_empty());
    }
}
